        .register-container { background: var(--white); padding: 40px; border-radius: var(--radius); box-shadow: 0 10px 25px -5px rgba(0,0,0,0.1); width: 100%; max-width: 450px; }
        .form-title { text-align: center; margin-bottom: 30px; font-size: 24px; font-weight: 700; }
