        .form-label { display: block; margin-bottom: 8px; font-weight: 500; font-size: 14px; }
        .form-input { width: 100%; padding: 12px; border: 1px solid var(--border); border-radius: var(--radius); font-size: 16px; outline: none; transition: 0.3s; }
        .form-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1); }

        .btn { width: 100%; padding: 12px; background: var(--primary); color: var(--white); border: none; border-radius: var(--radius); font-size: 16px; font-weight: 600; cursor: pointer; transition: 0.3s; margin-top: 10px; }
        .btn:hover { background: var(--secondary); }

        .form-footer { text-align: center; margin-top: 20px; font-size: 14px; color: var(--text-light); }

        .agreement { display: flex; align-items: flex-start; gap: 10px; font-size: 13px; color: var(--text-light); margin-bottom: 20px; }
        .agreement input { margin-top: 3px; }

        @media (max-width: 600px) {
            .register-container { padding: 25px; margin: 20px; }
        }
    </style>
    <script>
        // Simple validation mock
        document.addEventListener('DOMContentLoaded', function() {
            const form = document.querySelector('form');
            const btn = document.querySelector('.btn');

            form.addEventListener('submit', function(e) {
                e.preventDefault();

                const email = document.getElementById('email').value;
                const password = document.getElementById('password').value;

                if(email && password.length >= 6) {
                    btn.innerHTML = '注册成功，跳转中...';
                    btn.style.background = '#059669';
                    // Simulate delay
                    setTimeout(() => {
                        window.location.href = 'index.html';
                    }, 1500);
                } else {
                    alert('请填写有效的邮箱并确保密码长度大于 6 位');
                }
            });
        });
    </script>
</head>
